     1→export interface FogStroke {
     2→  x: number;
     3→  y: number;
     4→  radius: number;
     5→  mode: 'reveal' | 'fog';
     6→}
     7→
     8→export interface CanvasController {
     9→  loadImage(url: string): Promise<void>;
    10→  applyFogMask(base64: string): Promise<void>;
    11→  applyStroke(stroke: FogStroke): void;
    12→  drawBrushPreview(imgX: number, imgY: number, radius: number): void;
    13→  clearBrushPreview(): void;
    14→  screenToImage(clientX: number, clientY: number): { x: number; y: number };
    15→  getEventTarget(): HTMLCanvasElement;
    16→  clear(): void;
    17→}
    18→
    19→const FOG_ALPHA = 0.85;
    20→const FOG_FILL = `rgba(0,0,0,${FOG_ALPHA})`;
    21→
    22→async function decompress(data: Uint8Array): Promise<Uint8Array> {
    23→  // Try zlib (deflate with header) first, then raw deflate
    24→  for (const fmt of ['deflate', 'deflate-raw'] as CompressionFormat[]) {
    25→    try {
    26→      const ds = new DecompressionStream(fmt);
    27→      const writer = ds.writable.getWriter();
    28→      const reader = ds.readable.getReader();
    29→      // Clone data to avoid detached buffer on retry
    30→      writer.write(data.slice());
    31→      writer.close();
    32→      const chunks: Uint8Array[] = [];
    33→      for (;;) {
    34→        const { done, value } = await reader.read();
    35→        if (done) break;
    36→        chunks.push(value);
    37→      }
    38→      const total = chunks.reduce((n, c) => n + c.length, 0);
    39→      const out = new Uint8Array(total);
    40→      let off = 0;
    41→      for (const c of chunks) { out.set(c, off); off += c.length; }
    42→      return out;
    43→    } catch {
    44→      // try next format
    45→    }
    46→  }
    47→  throw new Error('Failed to decompress fog mask');
    48→}
    49→
    50→export function initCanvas(container: HTMLElement): CanvasController {
    51→  const wrapper = document.createElement('div');
    52→  wrapper.style.cssText = 'position:relative;flex-shrink:0;';
    53→  container.appendChild(wrapper);
    54→
    55→  function makeCanvas(): HTMLCanvasElement {
    56→    const c = document.createElement('canvas');
    57→    c.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;';
    58→    wrapper.appendChild(c);
    59→    return c;
    60→  }
    61→
    62→  const mapCanvas = makeCanvas();
    63→  const fogCanvas = makeCanvas();
    64→  const previewCanvas = makeCanvas();
    65→  previewCanvas.style.pointerEvents = 'none';
    66→
    67→  const mapCtx = mapCanvas.getContext('2d')!;
    68→  const fogCtx = fogCanvas.getContext('2d')!;
    69→  const previewCtx = previewCanvas.getContext('2d')!;
    70→
    71→  let imgW = 0;
    72→  let imgH = 0;
    73→
    74→  function sizeAll(w: number, h: number) {
    75→    imgW = w;
    76→    imgH = h;
    77→    for (const c of [mapCanvas, fogCanvas, previewCanvas]) {
    78→      c.width = w;
    79→      c.height = h;
    80→    }
    81→    const cw = container.clientWidth || 800;
    82→    const ch = container.clientHeight || 600;
    83→    const scale = Math.min(cw / w, ch / h);
    84→    wrapper.style.width = `${Math.round(w * scale)}px`;
    85→    wrapper.style.height = `${Math.round(h * scale)}px`;
    86→  }
    87→
    88→  function fillFog() {
    89→    fogCtx.save();
    90→    fogCtx.globalCompositeOperation = 'source-over';
    91→    fogCtx.fillStyle = FOG_FILL;
    92→    fogCtx.fillRect(0, 0, imgW, imgH);
    93→    fogCtx.restore();
    94→  }
    95→
    96→  return {
    97→    async loadImage(url: string) {
    98→      const img = new Image();
    99→      await new Promise<void>((res, rej) => {
   100→        img.onload = () => res();
   101→        img.onerror = () => rej(new Error(`Failed to load image: ${url}`));
   102→        img.src = url;
   103→      });
   104→      sizeAll(img.naturalWidth, img.naturalHeight);
   105→      mapCtx.clearRect(0, 0, imgW, imgH);
   106→      mapCtx.drawImage(img, 0, 0);
   107→      fogCtx.clearRect(0, 0, imgW, imgH);
   108→      fillFog();
   109→      previewCtx.clearRect(0, 0, imgW, imgH);
   110→    },
   111→
   112→    async applyFogMask(base64: string) {
   113→      const bin = atob(base64);
   114→      const bytes = new Uint8Array(bin.length);
   115→      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
   116→      const view = new DataView(bytes.buffer);
   117→      const w = view.getUint32(0, false);
   118→      const h = view.getUint32(4, false);
   119→      const pixels = await decompress(bytes.slice(8));
   120→      if (imgW !== w || imgH !== h) sizeAll(w, h);
   121→      const id = fogCtx.createImageData(w, h);
   122→      for (let i = 0; i < pixels.length; i++) {
   123→        const v = pixels[i];
   124→        id.data[i * 4 + 0] = 0;
   125→        id.data[i * 4 + 1] = 0;
   126→        id.data[i * 4 + 2] = 0;
   127→        id.data[i * 4 + 3] = Math.round(v * FOG_ALPHA);
   128→      }
   129→      fogCtx.putImageData(id, 0, 0);
   130→    },
   131→
   132→    applyStroke(stroke: FogStroke) {
   133→      if (imgW === 0) return;
   134→      fogCtx.save();
   135→      fogCtx.beginPath();
   136→      fogCtx.arc(stroke.x, stroke.y, stroke.radius, 0, Math.PI * 2);
   137→      if (stroke.mode === 'reveal') {
   138→        fogCtx.globalCompositeOperation = 'destination-out';
   139→        fogCtx.fillStyle = 'rgba(0,0,0,1)';
   140→      } else {
   141→        fogCtx.globalCompositeOperation = 'source-over';
   142→        fogCtx.fillStyle = FOG_FILL;
   143→      }
   144→      fogCtx.fill();
   145→      fogCtx.restore();
   146→    },
   147→
   148→    drawBrushPreview(imgX: number, imgY: number, radius: number) {
   149→      if (imgW === 0) return;
   150→      previewCtx.clearRect(0, 0, imgW, imgH);
   151→      previewCtx.save();
   152→      previewCtx.strokeStyle = 'rgba(255,255,255,0.7)';
   153→      previewCtx.lineWidth = Math.max(1, 2 * (imgW / (wrapper.clientWidth || imgW)));
   154→      previewCtx.beginPath();
   155→      previewCtx.arc(imgX, imgY, radius, 0, Math.PI * 2);
   156→      previewCtx.stroke();
   157→      previewCtx.restore();
   158→    },
   159→
   160→    clearBrushPreview() {
   161→      if (imgW > 0) previewCtx.clearRect(0, 0, imgW, imgH);
   162→    },
   163→
   164→    screenToImage(clientX: number, clientY: number) {
   165→      const rect = fogCanvas.getBoundingClientRect();
   166→      return {
   167→        x: (clientX - rect.left) * (imgW / (rect.width || 1)),
   168→        y: (clientY - rect.top) * (imgH / (rect.height || 1)),
   169→      };
   170→    },
   171→
   172→    getEventTarget() { return fogCanvas; },
   173→
   174→    clear() {
   175→      mapCtx.clearRect(0, 0, imgW, imgH);
   176→      fogCtx.clearRect(0, 0, imgW, imgH);
   177→      previewCtx.clearRect(0, 0, imgW, imgH);
   178→    },
   179→  };
   180→}
