     1→export type MessageHandler = (msg: Record<string, unknown>) => void;
     2→
     3→export interface WebSocketClient {
     4→  send(msg: Record<string, unknown>): void;
     5→  on(type: string, handler: MessageHandler): void;
     6→  close(): void;
     7→}
     8→
     9→export function connectGM(adventureId: string, password: string): WebSocketClient {
    10→  const handlers = new Map<string, MessageHandler[]>();
    11→  let ws: WebSocket | null = null;
    12→  let closed = false;
    13→  let backoff = 1000;
    14→
    15→  function emit(type: string, msg: Record<string, unknown>) {
    16→    for (const h of handlers.get(type) ?? []) {
    17→      try { h(msg); } catch (e) { console.error('ws handler error', e); }
    18→    }
    19→  }
    20→
    21→  function buildUrl(): string {
    22→    const u = new URL('/ws', window.location.href);
    23→    u.protocol = u.protocol === 'https:' ? 'wss:' : 'ws:';
    24→    u.searchParams.set('adventureId', adventureId);
    25→    u.searchParams.set('role', 'gm');
    26→    u.searchParams.set('password', password);
    27→    return u.toString();
    28→  }
    29→
    30→  function connect() {
    31→    if (closed) return;
    32→    try {
    33→      ws = new WebSocket(buildUrl());
    34→    } catch {
    35→      scheduleReconnect();
    36→      return;
    37→    }
    38→
    39→    ws.onopen = () => {
    40→      backoff = 1000;
    41→      emit('connect', {});
    42→    };
    43→
    44→    ws.onmessage = (ev) => {
    45→      try {
    46→        const msg = JSON.parse(ev.data as string) as Record<string, unknown>;
    47→        if (typeof msg?.type === 'string') emit(msg.type, msg);
    48→      } catch {}
    49→    };
    50→
    51→    ws.onerror = () => { ws?.close(); };
    52→
    53→    ws.onclose = () => {
    54→      ws = null;
    55→      if (closed) return;
    56→      emit('disconnect', {});
    57→      scheduleReconnect();
    58→    };
    59→  }
    60→
    61→  function scheduleReconnect() {
    62→    setTimeout(() => { backoff = Math.min(backoff * 2, 30000); connect(); }, backoff);
    63→  }
    64→
    65→  connect();
    66→
    67→  return {
    68→    send(msg: Record<string, unknown>) {
    69→      if (ws?.readyState === WebSocket.OPEN) {
    70→        ws.send(JSON.stringify(msg));
    71→      }
    72→    },
    73→    on(type: string, handler: MessageHandler) {
    74→      if (!handlers.has(type)) handlers.set(type, []);
    75→      handlers.get(type)!.push(handler);
    76→    },
    77→    close() {
    78→      closed = true;
    79→      ws?.close();
    80→    },
    81→  };
    82→}
