     1→export interface Adventure {
     2→  id: string;
     3→  name: string;
     4→  player_link: string;
     5→  active_image_id: string | null;
     6→  gm_password: string;
     7→}
     8→
     9→export interface ImageRecord {
    10→  id: string;
    11→  adventure_id: string;
    12→  filename: string;
    13→  original_name: string;
    14→  width: number;
    15→  height: number;
    16→  sort_order: number;
    17→}
    18→
    19→function gmHeaders(password: string): HeadersInit {
    20→  return { 'X-GM-Password': password };
    21→}
    22→
    23→async function checkOk(res: Response): Promise<Response> {
    24→  if (!res.ok) {
    25→    const text = await res.text().catch(() => res.statusText);
    26→    throw new Error(`HTTP ${res.status}: ${text}`);
    27→  }
    28→  return res;
    29→}
    30→
    31→export async function createAdventure(name: string, password: string): Promise<Adventure> {
    32→  const res = await fetch('/api/adventures', {
    33→    method: 'POST',
    34→    headers: { 'Content-Type': 'application/json' },
    35→    body: JSON.stringify({ name, gmPassword: password }),
    36→  });
    37→  return (await checkOk(res)).json();
    38→}
    39→
    40→export async function getAdventure(adventureId: string, password: string): Promise<Adventure> {
    41→  const res = await fetch(`/api/adventures/${adventureId}`, {
    42→    headers: gmHeaders(password),
    43→  });
    44→  return (await checkOk(res)).json();
    45→}
    46→
    47→export async function uploadImage(adventureId: string, password: string, file: File): Promise<ImageRecord> {
    48→  const form = new FormData();
    49→  form.append('file', file);
    50→  const res = await fetch(`/api/adventures/${adventureId}/images`, {
    51→    method: 'POST',
    52→    headers: gmHeaders(password),
    53→    body: form,
    54→  });
    55→  return (await checkOk(res)).json();
    56→}
    57→
    58→export async function listImages(adventureId: string, password: string): Promise<ImageRecord[]> {
    59→  const res = await fetch(`/api/adventures/${adventureId}/images`, {
    60→    headers: gmHeaders(password),
    61→  });
    62→  return (await checkOk(res)).json();
    63→}
    64→
    65→export async function deleteImage(adventureId: string, password: string, imageId: string): Promise<void> {
    66→  const res = await fetch(`/api/adventures/${adventureId}/images/${imageId}`, {
    67→    method: 'DELETE',
    68→    headers: gmHeaders(password),
    69→  });
    70→  await checkOk(res);
    71→}
    72→
    73→export async function switchActiveImage(adventureId: string, password: string, imageId: string): Promise<void> {
    74→  const res = await fetch(`/api/adventures/${adventureId}/active-image`, {
    75→    method: 'PUT',
    76→    headers: { ...gmHeaders(password), 'Content-Type': 'application/json' },
    77→    body: JSON.stringify({ imageId }),
    78→  });
    79→  await checkOk(res);
    80→}
