     1→import { connectGM } from './websocket';
     2→import { initCanvas } from './canvas';
     3→import type { FogStroke } from './canvas';
     4→import * as api from './api';
     5→
     6→// --- URL params ---
     7→const fragment = new URLSearchParams(location.hash.slice(1));
     8→const adventureId = fragment.get('id') ?? '';
     9→const password = fragment.get('password') ?? '';
    10→
    11→if (!adventureId || !password) {
    12→  document.body.innerHTML = '<p style="padding:2rem">Missing adventure ID or password. <a href="/">Return home</a></p>';
    13→  throw new Error('Missing params');
    14→}
    15→
    16→// --- State ---
    17→let brushRadius = 50;
    18→let brushMode: 'reveal' | 'fog' = 'reveal';
    19→let activeImageId: string | null = null;
    20→let imageList: api.ImageRecord[] = [];
    21→
    22→// --- DOM ---
    23→const adventureNameEl = document.getElementById('adventure-name')!;
    24→const inviteLinkEl = document.getElementById('invite-link')!;
    25→const copyInviteBtn = document.getElementById('copy-invite')!;
    26→const brushSizeSlider = document.getElementById('brush-size') as HTMLInputElement;
    27→const brushSizeLabel = document.getElementById('brush-size-label')!;
    28→const modeRevealBtn = document.getElementById('mode-reveal')!;
    29→const modeFogBtn = document.getElementById('mode-fog')!;
    30→const gallery = document.getElementById('gallery')!;
    31→const uploadInput = document.getElementById('upload-input') as HTMLInputElement;
    32→const statusBar = document.getElementById('status-bar')!;
    33→const canvasArea = document.getElementById('canvas-area')!;
    34→
    35→// --- Canvas ---
    36→const canvasCtrl = initCanvas(canvasArea);
    37→
    38→// --- WebSocket ---
    39→const ws = connectGM(adventureId, password);
    40→
    41→ws.on('connect', () => { statusBar.textContent = ''; });
    42→ws.on('disconnect', () => { statusBar.textContent = 'Reconnecting\u2026'; });
    43→ws.on('error', (msg) => { console.error('WS error', msg); });
    44→
    45→ws.on('joined', async (msg) => {
    46→  const adv = msg.adventure as { id: string; name: string; activeImageId: string | null };
    47→  adventureNameEl.textContent = adv.name;
    48→
    49→  try {
    50→    const advData = await api.getAdventure(adventureId, password);
    51→    const inviteUrl = `${location.origin}/player#link=${encodeURIComponent(advData.player_link)}`;
    52→    inviteLinkEl.textContent = inviteUrl;
    53→    copyInviteBtn.onclick = () => {
    54→      navigator.clipboard.writeText(inviteUrl).catch(() => {});
    55→    };
    56→  } catch {}
    57→
    58→  activeImageId = adv.activeImageId;
    59→  imageList = await api.listImages(adventureId, password);
    60→  renderGallery();
    61→
    62→  if (activeImageId) {
    63→    const img = imageList.find(i => i.id === activeImageId);
    64→    if (img) {
    65→      await canvasCtrl.loadImage(`/uploads/${img.filename}`);
    66→      if (typeof msg.fogMask === 'string') {
    67→        await canvasCtrl.applyFogMask(msg.fogMask);
    68→      }
    69→    }
    70→  }
    71→});
    72→
    73→ws.on('fog:stroke', (msg) => {
    74→  if (msg.imageId === activeImageId) {
    75→    canvasCtrl.applyStroke(msg.stroke as FogStroke);
    76→  }
    77→});
    78→
    79→ws.on('fog:stroke:batch', (msg) => {
    80→  if (msg.imageId === activeImageId) {
    81→    for (const stroke of msg.strokes as FogStroke[]) {
    82→      canvasCtrl.applyStroke(stroke);
    83→    }
    84→  }
    85→});
    86→
    87→ws.on('map:switched', async (msg) => {
    88→  activeImageId = msg.imageId as string;
    89→  imageList = await api.listImages(adventureId, password);
    90→  const img = imageList.find(i => i.id === activeImageId);
    91→  if (img) {
    92→    await canvasCtrl.loadImage(`/uploads/${img.filename}`);
    93→    if (typeof msg.fogMask === 'string') {
    94→      await canvasCtrl.applyFogMask(msg.fogMask);
    95→    }
    96→  }
    97→  renderGallery();
    98→});
    99→
   100→// --- Gallery ---
   101→function renderGallery() {
   102→  gallery.innerHTML = '';
   103→  for (const img of imageList) {
   104→    const item = document.createElement('div');
   105→    item.className = 'gallery-item' + (img.id === activeImageId ? ' active' : '');
   106→
   107→    const thumb = document.createElement('img');
   108→    thumb.src = `/uploads/${img.filename}`;
   109→    thumb.alt = img.original_name;
   110→    thumb.title = img.original_name;
   111→    item.appendChild(thumb);
   112→
   113→    item.addEventListener('click', () => {
   114→      ws.send({ type: 'map:switch', imageId: img.id });
   115→    });
   116→    gallery.appendChild(item);
   117→  }
   118→}
   119→
   120→// --- Upload ---
   121→uploadInput.addEventListener('change', async () => {
   122→  const file = uploadInput.files?.[0];
   123→  if (!file) return;
   124→  try {
   125→    await api.uploadImage(adventureId, password, file);
   126→    imageList = await api.listImages(adventureId, password);
   127→    renderGallery();
   128→  } catch (e) {
   129→    console.error('Upload failed', e);
   130→  }
   131→  uploadInput.value = '';
   132→});
   133→
   134→// --- Brush controls ---
   135→brushSizeSlider.addEventListener('input', () => {
   136→  brushRadius = parseInt(brushSizeSlider.value, 10);
   137→  brushSizeLabel.textContent = `${brushRadius}px`;
   138→});
   139→
   140→function setMode(mode: 'reveal' | 'fog') {
   141→  brushMode = mode;
   142→  modeRevealBtn.classList.toggle('active', mode === 'reveal');
   143→  modeFogBtn.classList.toggle('active', mode === 'fog');
   144→}
   145→
   146→modeRevealBtn.addEventListener('click', () => setMode('reveal'));
   147→modeFogBtn.addEventListener('click', () => setMode('fog'));
   148→
   149→// --- Brush interaction ---
   150→const eventTarget = canvasCtrl.getEventTarget();
   151→let isDrawing = false;
   152→const pending: FogStroke[] = [];
   153→let lastFlush = 0;
   154→const FLUSH_INTERVAL = 1000 / 60;
   155→
   156→function makeStroke(clientX: number, clientY: number): FogStroke {
   157→  const pos = canvasCtrl.screenToImage(clientX, clientY);
   158→  return { x: pos.x, y: pos.y, radius: brushRadius, mode: brushMode };
   159→}
   160→
   161→function flushPending() {
   162→  if (pending.length === 0) return;
   163→  if (pending.length === 1) {
   164→    ws.send({ type: 'fog:stroke', stroke: pending[0] });
   165→  } else {
   166→    ws.send({ type: 'fog:stroke:batch', strokes: pending.slice() });
   167→  }
   168→  pending.length = 0;
   169→  lastFlush = Date.now();
   170→}
   171→
   172→eventTarget.addEventListener('pointerdown', (ev: PointerEvent) => {
   173→  if (!activeImageId) return;
   174→  isDrawing = true;
   175→  eventTarget.setPointerCapture(ev.pointerId);
   176→  const stroke = makeStroke(ev.clientX, ev.clientY);
   177→  canvasCtrl.applyStroke(stroke);
   178→  pending.push(stroke);
   179→  if (Date.now() - lastFlush >= FLUSH_INTERVAL) flushPending();
   180→});
   181→
   182→eventTarget.addEventListener('pointermove', (ev: PointerEvent) => {
   183→  const pos = canvasCtrl.screenToImage(ev.clientX, ev.clientY);
   184→  canvasCtrl.drawBrushPreview(pos.x, pos.y, brushRadius);
   185→  if (!isDrawing) return;
   186→  const stroke = makeStroke(ev.clientX, ev.clientY);
   187→  canvasCtrl.applyStroke(stroke);
   188→  pending.push(stroke);
   189→  if (Date.now() - lastFlush >= FLUSH_INTERVAL) flushPending();
   190→});
   191→
   192→eventTarget.addEventListener('pointerup', () => {
   193→  if (!isDrawing) return;
   194→  isDrawing = false;
   195→  flushPending();
   196→});
   197→
   198→eventTarget.addEventListener('pointerleave', () => {
   199→  canvasCtrl.clearBrushPreview();
   200→  if (isDrawing) {
   201→    isDrawing = false;
   202→    flushPending();
   203→  }
   204→});
   205→

