   133→export function parseMessage(raw: string): ClientMessage | null {
   134→  try {
   135→    const msg = JSON.parse(raw);
   136→    if (!msg || typeof msg !== "object" || typeof msg.type !== "string")
   137→      return null;
   138→    return msg as ClientMessage;
   139→  } catch {
   140→    return null;
   141→  }
   142→}
