     1→import type { Database } from "bun:sqlite";
     2→import type { Server, ServerWebSocket } from "bun";
     3→import type { WsData, FogMask } from "../types";
     4→import { getAdventure, getAdventureByPlayerLink, setActiveImage } from "../db/adventures";
     5→import { getImage } from "../db/images";
     6→import { createToken, getTokensByAdventure, updateTokenPosition, deleteToken } from "../db/tokens";
     7→import { createMask, applyStroke, applyStrokes } from "../fog/mask";
     8→import { serializeMask, saveFogMask, loadFogMask } from "../fog/serialize";
     9→import {
    10→  registerConnection,
    11→  unregisterConnection,
    12→  getConnection,
    13→} from "./connections";
    14→import { parseMessage, serializeMessage } from "./messages";
    15→
    16→// ---- Fog mask in-memory cache ----
    17→
    18→const fogMaskCache = new Map<string, FogMask>(); // keyed by imageId
    19→const saveTimers = new Map<string, ReturnType<typeof setTimeout>>();
    20→
    21→async function getFogMaskForImage(db: Database, imageId: string): Promise<FogMask> {
    22→  if (fogMaskCache.has(imageId)) return fogMaskCache.get(imageId)!;
    23→  const loaded = await loadFogMask(db, imageId);
    24→  if (loaded) {
    25→    fogMaskCache.set(imageId, loaded);
    26→    return loaded;
    27→  }
    28→  const image = getImage(db, imageId);
    29→  if (!image) throw new Error(`Image ${imageId} not found`);
    30→  const mask = createMask(image.width, image.height);
    31→  fogMaskCache.set(imageId, mask);
    32→  return mask;
    33→}
    34→
    35→function scheduleSave(db: Database, imageId: string): void {
    36→  const existing = saveTimers.get(imageId);
    37→  if (existing) clearTimeout(existing);
    38→  const timer = setTimeout(async () => {
    39→    saveTimers.delete(imageId);
    40→    const mask = fogMaskCache.get(imageId);
    41→    if (mask) await saveFogMask(db, imageId, mask);
    42→  }, 1000);
    43→  saveTimers.set(imageId, timer);
    44→}
    45→
    46→async function maskToBase64(mask: FogMask): Promise<string> {
    47→  const buf = await serializeMask(mask);
    48→  return buf.toString("base64");
    49→}
    50→
    51→// ---- WebSocket upgrade (called from fetch handler) ----
    52→
    53→export function handleWsUpgrade(
    54→  req: Request,
    55→  db: Database,
    56→  server: Server
    57→): Response | undefined {
    58→  const url = new URL(req.url);
    59→  const adventureId = url.searchParams.get("adventureId");
    60→  const role = url.searchParams.get("role") as "gm" | "player" | null;
    61→  const password = url.searchParams.get("password");
    62→  const playerLink = url.searchParams.get("playerLink");
    63→  const playerName = url.searchParams.get("playerName");
    64→  const playerColor = url.searchParams.get("playerColor");
    65→
    66→  if (!adventureId || !role) {
    67→    return new Response("adventureId and role are required", { status: 400 });
    68→  }
    69→  if (role !== "gm" && role !== "player") {
    70→    return new Response("role must be gm or player", { status: 400 });
    71→  }
    72→
    73→  const adventure = getAdventure(db, adventureId);
    74→  if (!adventure) {
    75→    return new Response("Adventure not found", { status: 404 });
    76→  }
    77→
    78→  let tokenId: string | undefined;
    79→
    80→  if (role === "gm") {
    81→    if (!password || password !== adventure.gm_password) {
    82→      return new Response("Invalid password", { status: 401 });
    83→    }
    84→  } else {
    85→    if (!playerLink) {
    86→      return new Response("playerLink is required for players", { status: 400 });
    87→    }
    88→    const linked = getAdventureByPlayerLink(db, playerLink);
    89→    if (!linked || linked.id !== adventureId) {
    90→      return new Response("Invalid player link", { status: 401 });
    91→    }
    92→    if (!playerName || !playerColor) {
    93→      return new Response("playerName and playerColor are required", { status: 400 });
    94→    }
    95→    const token = createToken(db, { adventureId, name: playerName, color: playerColor });
    96→    tokenId = token.id;
    97→  }
    98→
    99→  const wsData: WsData = {
   100→    adventureId,
   101→    role,
   102→    playerName: playerName ?? undefined,
   103→    playerColor: playerColor ?? undefined,
   104→    tokenId,
   105→  };
   106→
   107→  const upgraded = server.upgrade(req, { data: wsData });
   108→  if (!upgraded) {
   109→    return new Response("WebSocket upgrade failed", { status: 500 });
   110→  }
   111→  // Return undefined so Bun completes the WebSocket handshake
   112→  return undefined;
   113→}
   114→
   115→// ---- WebSocket handlers ----
   116→
   117→export function createWsHandlers(db: Database) {
   118→  return {
   119→    async open(ws: ServerWebSocket<WsData>) {
   120→      const { adventureId, role, playerName, playerColor, tokenId } = ws.data;
   121→      registerConnection(ws, { adventureId, role, playerName, playerColor, tokenId });
   122→
   123→      const adventure = getAdventure(db, adventureId)!;
   124→      const tokens = getTokensByAdventure(db, adventureId);
   125→
   126→      let fogMask: string | null = null;
   127→      if (adventure.active_image_id) {
   128→        try {
   129→          const mask = await getFogMaskForImage(db, adventure.active_image_id);
   130→          fogMask = await maskToBase64(mask);
   131→        } catch {
   132→          fogMask = null;
   133→        }
   134→      }
   135→
   136→      ws.send(
   137→        serializeMessage({
   138→          type: "joined",
   139→          adventure: {
   140→            id: adventure.id,
   141→            name: adventure.name,
   142→            activeImageId: adventure.active_image_id,
   143→          },
   144→          tokens,
   145→          fogMask,
   146→        })
   147→      );
   148→
   149→      if (role === "player" && playerName && playerColor) {
   150→        ws.publish(
   151→          `adventure:${adventureId}`,
   152→          serializeMessage({ type: "player:joined", playerName, playerColor })
   153→        );
   154→        if (tokenId) {
   155→          const token = tokens.find((t) => t.id === tokenId);
   156→          if (token) {
   157→            ws.publish(
   158→              `adventure:${adventureId}`,
   159→              serializeMessage({ type: "token:added", token })
   160→            );
   161→          }
   162→        }
   163→      }
   164→    },
   165→
   166→    async message(ws: ServerWebSocket<WsData>, raw: string | Buffer) {
   167→      const conn = getConnection(ws);
   168→      if (!conn) return;
   169→
   170→      const msg = parseMessage(typeof raw === "string" ? raw : raw.toString());
   171→      if (!msg) {
   172→        ws.send(serializeMessage({ type: "error", message: "Invalid message format" }));
   173→        return;
   174→      }
   175→
   176→      const { adventureId } = conn;
   177→      const topic = `adventure:${adventureId}`;
   178→
   179→      switch (msg.type) {
   180→        case "join": {
   181→          ws.send(serializeMessage({ type: "error", message: "Already joined" }));
   182→          break;
   183→        }
   184→
   185→        case "fog:stroke": {
   186→          if (conn.role !== "gm") {
   187→            ws.send(serializeMessage({ type: "error", message: "Only GM can send fog strokes" }));
   188→            break;
   189→          }
   190→          const adv = getAdventure(db, adventureId);
   191→          if (!adv?.active_image_id) {
   192→            ws.send(serializeMessage({ type: "error", message: "No active image" }));
   193→            break;
   194→          }
   195→          const imageId = adv.active_image_id;
   196→          const mask = await getFogMaskForImage(db, imageId);
   197→          applyStroke(mask, msg.stroke);
   198→          scheduleSave(db, imageId);
   199→          ws.publish(topic, serializeMessage({ type: "fog:stroke", stroke: msg.stroke, imageId }));
   200→          break;
   201→        }
   202→
   203→        case "fog:stroke:batch": {
   204→          if (conn.role !== "gm") {
   205→            ws.send(serializeMessage({ type: "error", message: "Only GM can send fog strokes" }));
   206→            break;
   207→          }
   208→          const adv = getAdventure(db, adventureId);
   209→          if (!adv?.active_image_id) {
   210→            ws.send(serializeMessage({ type: "error", message: "No active image" }));
   211→            break;
   212→          }
   213→          const imageId = adv.active_image_id;
   214→          const mask = await getFogMaskForImage(db, imageId);
   215→          applyStrokes(mask, msg.strokes);
   216→          scheduleSave(db, imageId);
   217→          ws.publish(topic, serializeMessage({ type: "fog:stroke:batch", strokes: msg.strokes, imageId }));
   218→          break;
   219→        }
   220→
   221→        case "token:move": {
   222→          if (!conn.tokenId || conn.tokenId !== msg.tokenId) {
   223→            ws.send(serializeMessage({ type: "error", message: "You do not own this token" }));
   224→            break;
   225→          }
   226→          updateTokenPosition(db, msg.tokenId, msg.x, msg.y);
   227→          const moved = serializeMessage({
   228→            type: "token:moved",
   229→            tokenId: msg.tokenId,
   230→            x: msg.x,
   231→            y: msg.y,
   232→          });
   233→          ws.send(moved);
   234→          ws.publish(topic, moved);
   235→          break;
   236→        }
   237→
   238→        case "map:switch": {
   239→          if (conn.role !== "gm") {
   240→            ws.send(serializeMessage({ type: "error", message: "Only GM can switch maps" }));
   241→            break;
   242→          }
   243→          try {
   244→            setActiveImage(db, adventureId, msg.imageId);
   245→          } catch {
   246→            ws.send(serializeMessage({ type: "error", message: "Invalid image" }));
   247→            break;
   248→          }
   249→          let fogMask: string | null = null;
   250→          try {
   251→            const mask = await getFogMaskForImage(db, msg.imageId);
   252→            fogMask = await maskToBase64(mask);
   253→          } catch {
   254→            fogMask = null;
   255→          }
   256→          const switched = serializeMessage({
   257→            type: "map:switched",
   258→            imageId: msg.imageId,
   259→            fogMask,
   260→          });
   261→          ws.send(switched);
   262→          ws.publish(topic, switched);
   263→          break;
   264→        }
   265→
   266→        case "ping": {
   267→          ws.send(serializeMessage({ type: "pong" }));
   268→          break;
   269→        }
   270→
   271→        default: {
   272→          ws.send(serializeMessage({ type: "error", message: "Unknown message type" }));
   273→        }
   274→      }
   275→    },
   276→
   277→    close(ws: ServerWebSocket<WsData>) {
   278→      const info = unregisterConnection(ws);
   279→      if (!info) return;
   280→
   281→      const topic = `adventure:${info.adventureId}`;
   282→
   283→      if (info.role === "player" && info.tokenId) {
   284→        deleteToken(db, info.tokenId);
   285→        ws.publish(topic, serializeMessage({ type: "token:removed", tokenId: info.tokenId }));
   286→      }
   287→
   288→      if (info.playerName) {
   289→        ws.publish(topic, serializeMessage({ type: "player:left", playerName: info.playerName }));
   290→      }
   291→    },
   292→  };
   293→}
