    24→  const url = new URL(req.url);
    25→  const { pathname } = url;
    26→  const segments = pathname.split("/").filter(Boolean);
    27→
    28→  if (req.method === "GET" && pathname === "/") {
    29→    try {
    30→      const html = readFileSync(join(publicDir, "index.html"), "utf-8");
