    32→    } catch {
    33→      return new Response("Not Found", { status: 404 });
    34→    }
    35→  }
    36→
    37→  if (req.method === "GET" && (pathname === "/gm" || pathname === "/player")) {
    38→    const fileName = pathname === "/gm" ? "gm.html" : "player.html";
    39→    try {
    40→      const html = readFileSync(join(publicDir, fileName), "utf-8");
    41→      return new Response(html, { headers: { "Content-Type": "text/html" } });
    42→    } catch {
    43→      return new Response("Not Found", { status: 404 });
    44→    }
    45→  }
    46→
    47→  if (req.method === "GET" && (pathname.startsWith("/dist/") || pathname.startsWith("/css/"))) {
    48→    const filePath = join(publicDir, pathname);
    49→    const file = Bun.file(filePath);
