    80→      return new Response("Not Found", { status: 404 });
    81→    }
    82→  }
    83→
    84→  if (segments[0] === "api" && segments[1] === "adventures" && db) {
    85→    return handleAdventureRoutes(req, db, uploadsDir, segments);
    86→  }
    87→
    88→  return new Response("Not Found", { status: 404 });
    89→}
    90→
    91→async function handleAdventureRoutes(
    92→  req: Request,
    93→  db: Database,
    94→  uploadsDir: string,
    95→  segments: string[]
    96→): Promise<Response> {
    97→  const json = (data: unknown, status = 200) =>
    98→    new Response(JSON.stringify(data), {
    99→      status,
   100→      headers: { "Content-Type": "application/json" },
   101→    });
   102→  const error = (msg: string, status: number) => json({ error: msg }, status);
   103→
   104→  // POST /api/adventures
   105→  if (req.method === "POST" && segments.length === 2) {
   106→    let body: { name?: unknown; gmPassword?: unknown };
   107→    try {
   108→      body = await req.json();
   109→    } catch {
   110→      return error("Invalid JSON", 400);
   111→    }
   112→    if (!body.name || typeof body.name !== "string" || body.name.trim() === "") {
   113→      return error("name is required", 400);
   114→    }
   115→    if (
   116→      !body.gmPassword ||
   117→      typeof body.gmPassword !== "string" ||
   118→      body.gmPassword.trim() === ""
   119→    ) {
   120→      return error("gmPassword is required", 400);
   121→    }
   122→    const adventure = createAdventure(db, {
   123→      name: body.name.trim(),
   124→      gmPassword: body.gmPassword,
   125→    });
   126→    return json(adventure, 201);
   127→  }
   128→
   129→  // GET /api/adventures/join/:playerLink
   130→  if (req.method === "GET" && segments[2] === "join" && segments.length === 4) {
   131→    const adventure = getAdventureByPlayerLink(db, segments[3]);
   132→    if (!adventure) return error("Not found", 404);
   133→    return json({
   134→      id: adventure.id,
   135→      name: adventure.name,
   136→      activeImageId: adventure.active_image_id,
   137→    });
   138→  }
   139→
   140→  // Routes with :id
   141→  if (segments.length >= 3) {
   142→    const id = segments[2];
   143→
   144→    // GET /api/adventures/:id
   145→    if (req.method === "GET" && segments.length === 3) {
   146→      const adventure = getAdventure(db, id);
   147→      if (!adventure) return error("Not found", 404);
   148→      if (req.headers.get("X-GM-Password") !== adventure.gm_password)
   149→        return error("Unauthorized", 401);
   150→      return json(adventure);
   151→    }
   152→
   153→    // PUT /api/adventures/:id/active-image
   154→    if (
   155→      req.method === "PUT" &&
   156→      segments[3] === "active-image" &&
   157→      segments.length === 4
   158→    ) {
   159→      const adventure = getAdventure(db, id);
   160→      if (!adventure) return error("Not found", 404);
   161→      if (req.headers.get("X-GM-Password") !== adventure.gm_password)
   162→        return error("Unauthorized", 401);
   163→
   164→      let body: { imageId?: unknown };
   165→      try {
   166→        body = await req.json();
   167→      } catch {
   168→        return error("Invalid JSON", 400);
   169→      }
   170→
   171→      if (body.imageId === null) {
   172→        db.run(`UPDATE adventures SET active_image_id = NULL WHERE id = ?`, [id]);
   173→        return json(getAdventure(db, id));
   174→      }
   175→      if (!body.imageId || typeof body.imageId !== "string") {
   176→        return error("imageId must be a string or null", 400);
   177→      }
   178→      try {
   179→        setActiveImage(db, id, body.imageId);
   180→      } catch {
   181→        return error("Image does not belong to this adventure", 400);
   182→      }
   183→      return json(getAdventure(db, id));
   184→    }
   185→
   186→    // POST /api/adventures/:id/images
   187→    if (
   188→      req.method === "POST" &&
   189→      segments[3] === "images" &&
   190→      segments.length === 4
   191→    ) {
   192→      const adventure = getAdventure(db, id);
   193→      if (!adventure) return error("Not found", 404);
   194→      if (req.headers.get("X-GM-Password") !== adventure.gm_password)
   195→        return error("Unauthorized", 401);
   196→
   197→      let formData: FormData;
   198→      try {
   199→        formData = await req.formData();
   200→      } catch {
   201→        return error("Invalid form data", 400);
   202→      }
   203→
   204→      const file = formData.get("file");
   205→      if (!file || !(file instanceof File)) return error("file is required", 400);
   206→      if (!file.type.startsWith("image/")) return error("file must be an image", 400);
   207→
   208→      const rawExt = file.name.split(".").pop() ?? "bin";
   209→      const ext = rawExt.replace(/[^a-zA-Z0-9]/g, "").substring(0, 10) || "bin";
   210→      const filename = `${crypto.randomUUID()}.${ext}`;
   211→      const filePath = join(uploadsDir, filename);
   212→
   213→      const buffer = await file.arrayBuffer();
   214→      writeFileSync(filePath, Buffer.from(buffer));
   215→
   216→      const imageRecord = createImageRecord(db, {
   217→        adventureId: id,
   218→        filename,
   219→        originalName: file.name,
   220→        width: 0,
   221→        height: 0,
   222→      });
   223→      return json(imageRecord, 201);
   224→    }
   225→
   226→    // GET /api/adventures/:id/images
   227→    if (
   228→      req.method === "GET" &&
   229→      segments[3] === "images" &&
   230→      segments.length === 4
   231→    ) {
   232→      const adventure = getAdventure(db, id);
   233→      if (!adventure) return error("Not found", 404);
   234→
   235→      const gmPassword = req.headers.get("X-GM-Password");
   236→      const playerLink = req.headers.get("X-Player-Link");
   237→
   238→      if (gmPassword !== adventure.gm_password) {
   239→        if (!playerLink) return error("Unauthorized", 401);
   240→        const linked = getAdventureByPlayerLink(db, playerLink);
   241→        if (!linked || linked.id !== id) return error("Unauthorized", 401);
   242→      }
   243→
   244→      return json(getImagesByAdventure(db, id));
   245→    }
   246→
   247→    // DELETE /api/adventures/:id/images/:imageId
   248→    if (
   249→      req.method === "DELETE" &&
   250→      segments[3] === "images" &&
   251→      segments.length === 5
   252→    ) {
   253→      const imageId = segments[4];
   254→      const adventure = getAdventure(db, id);
   255→      if (!adventure) return error("Not found", 404);
   256→      if (req.headers.get("X-GM-Password") !== adventure.gm_password)
   257→        return error("Unauthorized", 401);
   258→
   259→      const image = getImage(db, imageId);
   260→      if (!image || image.adventure_id !== id) return error("Not found", 404);
   261→
   262→      try {
   263→        unlinkSync(join(uploadsDir, image.filename));
   264→      } catch {
   265→        // file may already be gone
   266→      }
   267→      deleteImage(db, imageId);
   268→      return new Response(null, { status: 204 });
   269→    }
   270→  }
   271→
   272→  return new Response("Not Found", { status: 404 });
   273→}
